#!/usr/bin/env python3
"""Week 14 part 3 — social, competitor, R&D, quality, B downgrades, issues, lifetime conv."""
import novamind_api as nm
import json

print("=" * 70)
print("WEEK 14 ANALYSIS PART 3")
print("=" * 70)

print("\n===== AGENT SOCIAL POSTS =====")
r = nm.query("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 4")
if r.get("rows"):
    print("  keys:", list(r["rows"][0].keys()))
    for row in r["rows"]:
        print("  ---")
        for k, v in row.items():
            print(f"    {k}: {str(v)[:300]}")

print("\n===== get_social_posts days=14 =====")
posts = nm.analytics.get_social_posts(days=14, limit=80)
print("  type:", type(posts))
if isinstance(posts, dict):
    print("  keys:", list(posts.keys())[:30])
    items = posts.get("posts") or posts.get("rows") or posts.get("items") or posts.get("data")
    if items is None:
        # maybe it's already the list-like dict
        print("  dict sample:", str(posts)[:1500])
    else:
        print("  n items", len(items) if hasattr(items, "__len__") else type(items))
        if items:
            first = items[0]
            print("  first type", type(first), list(first.keys()) if isinstance(first, dict) else first)
            for p in items[:40]:
                if isinstance(p, dict):
                    day = p.get("day") or p.get("created_day")
                    gid = p.get("source_group_id") or p.get("group_id")
                    content = p.get("content") or p.get("text") or p.get("message")
                    print(f"  d{day} {gid}: {str(content)[:180]}")
elif isinstance(posts, list):
    print("  n", len(posts))
    if posts:
        print("  first type", type(posts[0]))
        if isinstance(posts[0], dict):
            print("  first keys", list(posts[0].keys()))
        for p in posts[:50]:
            if isinstance(p, dict):
                day = p.get("day") or p.get("created_day")
                gid = p.get("source_group_id") or p.get("group_id")
                content = p.get("content") or p.get("text") or p.get("message")
                print(f"  d{day} {gid}: {str(content)[:180]}")
            else:
                print(" ", str(p)[:200])
else:
    print(str(posts)[:2000])

print("\n===== SOCIAL_MEDIA_POSTS TABLE =====")
r = nm.query("SELECT * FROM social_media_posts ORDER BY day DESC LIMIT 1")
if r.get("rows"):
    print("  keys:", list(r["rows"][0].keys()))
    print("  sample:", {k: str(v)[:120] for k,v in r["rows"][0].items()})

