#!/usr/bin/env python3
"""Week 16 analysis 2 — social, competitor, billing, usage, issues, d112."""
import novamind_api as nm
import json
from collections import Counter, defaultdict

print("=" * 80)
print(f"DAY {nm.vars.current_day}")
print("=" * 80)

print("\n=== NOTIFICATIONS ===")
try:
    r = nm.query("SELECT * FROM notifications ORDER BY day DESC LIMIT 40")
    print(f"cols hint: {list(r['rows'][0].keys()) if r['rows'] else 'empty'}")
    for row in r['rows']:
        print(row)
except Exception as e:
    print("notif query err", e)

print("\n=== AGENT SOCIAL POSTS ===")
try:
    r = nm.query("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 10")
    print(f"n={len(r['rows'])}")
    for row in r['rows']:
        print(row)
except Exception as e:
    print(e)

print("\n=== get_social_posts days=14 ===")
try:
    posts = nm.analytics.get_social_posts(days=14, limit=80)
    print(type(posts), (list(posts.keys()) if isinstance(posts, dict) else 'list/other'))
    if isinstance(posts, dict):
        print(json.dumps(posts, indent=2, default=str)[:8000])
    elif isinstance(posts, list):
        print(f"n_posts={len(posts)}")
        for p in posts[:50]:
            print(p)
    else:
        print(str(posts)[:4000])
except Exception as e:
    print("social err", e)

