import novamind_api as nm

print("=== SOCIAL COMPETITOR / QUALITY ===")
posts = nm.analytics.get_social_posts(days=14, limit=200)
print("n posts returned", len(posts) if posts else 0)

# print recent posts with day
if posts:
    # handle both list of dicts and other formats
    if isinstance(posts, dict):
        print("posts is dict keys", posts.keys())
        rows = posts.get("posts") or posts.get("rows") or posts
    else:
        rows = posts
    # sort by day if possible
    def get_day(p):
        if isinstance(p, dict):
            return p.get("day", p.get("created_day", 0))
        return 0
    try:
        rows_sorted = sorted(rows, key=get_day)
    except Exception:
        rows_sorted = rows
    for p in rows_sorted:
        if isinstance(p, dict):
            d = p.get("day", p.get("created_day", "?"))
            content = p.get("content", p.get("text", ""))[:200]
            gid = p.get("source_group_id") or p.get("group_id")
            print(f"d{d} [{gid}] {content}")
        else:
            print(p)

