                print('  item0 type', type(v[0]))
                print('  item0', v[0] if not isinstance(v[0], (dict,list)) else json.dumps(v[0], default=str)[:500])
        else:
            s = str(v)
            print('  val', s[:400])
elif isinstance(posts, list):
    print('len', len(posts))
    print('item0', posts[0])
else:
    print(posts)
"

